package pub.module.system.api.util;import cn.hutool.extra.spring.SpringUtil;import lombok.extern.slf4j.Slf4j;import org.springframework.security.core.Authentication;import org.springframework.security.core.context.SecurityContextHolder;import pub.module.common.enums.ResultCodeEnum;import pub.module.common.exception.AuthException;import pub.module.common.exception.BizException;import pub.module.system.api.service.ApiSysUserService;import pub.module.system.api.service.dto.UserDTO;@Slf4jpublic class UserUtil {    public static UserDTO getCurrentSysUser() {        Authentication auth = SecurityContextHolder.getContext().getAuthentication();        UserDTO userDTO = SpringUtil.getBean(ApiSysUserService.class).getUserByUserCode(auth.getName());        if(userDTO==null){            throw new AuthException(ResultCodeEnum.AUTH_FAIL);        }        return userDTO;    }}